// Before: mutating main-actor state inside a sink
final class FeedViewModel {
  @MainActor private(set) var posts: [Post] = []
  private var bag = Set<AnyCancellable>()

  func start(_ upstream: AnyPublisher<[Post], Never>) {
    upstream
      .receive(on: DispatchQueue.main)
      .sink { [weak self] posts in
        self?.posts = posts          // error in Swift 6: main-actor state from a nonisolated closure
      }
      .store(in: &bag)
  }
}

// After: leave the pipeline, continue where the isolation is known
upstream
  .sink { [weak self] posts in
    Task { @MainActor in self?.posts = posts }
  }
  .store(in: &bag)

// Or bind straight into the published property — no sink, no closure
upstream
  .receive(on: DispatchQueue.main)
  .assign(to: &$posts)

// Or step out of Combine entirely where nothing is lost
for await posts in upstream.values {
  await MainActor.run { self.posts = posts }
}

final class ComposeViewController: UIViewController {
  private var bag = Set<AnyCancellable>()
  private let sendButton = UIButton(type: .system)
  private let textField = UITextField()

  override func viewDidLoad() {
    super.viewDidLoad()

    NotificationCenter.default
      .publisher(for: UIResponder.keyboardWillChangeFrameNotification)
      .compactMap { $0.userInfo?[UIResponder.keyboardFrameEndUserInfoKey] as? CGRect }
      .sink { [weak self] frame in self?.adjustInsets(for: frame) }
      .store(in: &bag)

    webView.publisher(for: \.estimatedProgress)      // KVO bridge
      .sink { [weak self] in self?.progressView.progress = Float($0) }
      .store(in: &bag)

    sendButton.publisher(for: .touchUpInside)        // written below, not built in
      .sink { [weak self] in self?.send() }
      .store(in: &bag)
  }
}

extension UIControl {
  func publisher(for event: UIControl.Event) -> AnyPublisher<Void, Never> {
    let subject = PassthroughSubject<Void, Never>()
    let action = UIAction { _ in subject.send(()) }
    addAction(action, for: event)
    return subject
      .handleEvents(receiveCancel: { [weak self] in self?.removeAction(action, for: event) })
      .eraseToAnyPublisher()
  }
}

