// Deferred: a fresh Future per subscription, so retry actually retries
func fetch(id: String) -> AnyPublisher<User, Error> {
  Deferred {
    Future { promise in
      Task {
        do { promise(.success(try await api.user(id))) }
        catch { promise(.failure(error)) }
      }
    }
  }
  .eraseToAnyPublisher()
}

// Cancellable version: own the Task and kill it when the subscription goes away
func cancellableFetch(id: String) -> AnyPublisher<User, Error> {
  Deferred { () -> AnyPublisher<User, Error> in
    let subject = PassthroughSubject<User, Error>()
    let task = Task {
      do {
        subject.send(try await api.user(id))
        subject.send(completion: .finished)
      } catch {
        subject.send(completion: .failure(error))
      }
    }
    return subject
      .handleEvents(receiveCancel: { task.cancel() })
      .eraseToAnyPublisher()
  }
  .eraseToAnyPublisher()
}

