final class CartViewModel: ObservableObject {
  @Published var items: [Item] = []
  @Published var coupon: String?
  @Published private(set) var total: Total = .zero
  private var bag = Set<AnyCancellable>()

  init() {
    // Trap: this sink runs from willSet, before `items` is assigned
    $items
      .sink { [weak self] newItems in
        print(newItems.count)          // 3 — the value being set
        print(self?.items.count ?? 0)  // 0 — the property still holds the old array
      }
      .store(in: &bag)

    // Fix 1: use what you were handed and pull other state through operators
    $items
      .combineLatest($coupon)
      .map { items, coupon in Total(items: items, coupon: coupon) }
      .assign(to: &$total)

    // Fix 2: hop a turn so the property is committed first.
    // Works, but it is a timing assumption, not a guarantee about ordering.
    $items
      .receive(on: DispatchQueue.main)
      .sink { [weak self] _ in self?.recalculateFromModel() }
      .store(in: &bag)

    // $items emits the current value on subscribe; drop it if you only want changes
    $items.dropFirst().sink { _ in }.store(in: &bag)
  }
}

