// Real backpressure: pull one at a time, ask for the next only when the work is done
final class SerialSink<Input>: Subscriber {
  typealias Failure = Never
  private var subscription: Subscription?
  private let work: (Input, @escaping () -> Void) -> Void

  init(work: @escaping (Input, @escaping () -> Void) -> Void) { self.work = work }

  func receive(subscription: Subscription) {
    self.subscription = subscription
    subscription.request(.max(1))                  // one, not .unlimited
  }
  func receive(_ input: Input) -> Subscribers.Demand {
    work(input) { [weak self] in self?.subscription?.request(.max(1)) }
    return .none                                   // no additional demand yet
  }
  func receive(completion: Subscribers.Completion<Never>) { subscription = nil }
}

