// Fix 1 — hop a turn. receive(on:) always defers, even when already on main.
events
  .receive(on: DispatchQueue.main)
  .sink { event in
    if event.needsFollowUp { events.send(.followUp(event)) }
  }
  .store(in: &bag)

// Fix 2 — no feedback at all: derive the follow-up and merge it in
let followUps = events
  .filter(\.needsFollowUp)
  .map(Event.followUp)

events
  .merge(with: followUps)
  .sink { handle($0) }
  .store(in: &bag)

