// A dead run reads like this:
//   1-query: receive subscription: (Published)
//   1-query: request unlimited
//   1-query: receive value: ("sw")
//   2-debounced: receive value: ("sw")
//   3-request: receive failure: (URLError(.timedOut))   <- the inner publisher failed
//   4-results: receive failure: (URLError(.timedOut))   <- it completed the outer chain
//   1-query: receive cancel                             <- upstream torn down
// Everything typed after this point is delivered to nobody.

// Same events, but shippable: Logger instead of stdout, behind a flag
extension Publisher {
  func trace(_ name: String, log: Logger) -> Publishers.HandleEvents<Self> {
    handleEvents(
      receiveSubscription: { _ in log.debug("\(name) subscribed") },
      receiveOutput: { _ in log.debug("\(name) value") },
      receiveCompletion: { log.debug("\(name) completion \(String(describing: $0))") },
      receiveCancel: { log.debug("\(name) cancelled") },
      receiveRequest: { log.debug("\(name) demand \(String(describing: $0))") }
    )
  }
}

